        });
    });

    describe("should render panel", () => {
        it("MSC3882 + MSC3886", async () => {
            const { container } = render(
                getComponent({
                    versions: makeVersions({
                        "org.matrix.msc3882": true,
                        "org.matrix.msc3886": true,
                    }),
                }),
            );
            expect(container).toMatchSnapshot();
        });
    });
});
