        const { container } = render(getComponent());
        expect(mockClient.getDevices).toHaveBeenCalled();

        await act(async () => {
            await flushPromises();
        });
        expect(container.getElementsByClassName("mx_Spinner").length).toBeFalsy();
    });

    it("removes spinner when device fetch fails", async () => {
